using System;using System.Reflection;using NUnit.Framework;
namespace LWS.TruckTeaParty.Tests {
 public sealed class TeaRulesTests {
  Type type;object rules;const BindingFlags Any=BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic;object Call(string n,params object[] a)=>type.GetMethod(n).Invoke(rules,a);T Get<T>(string n)=>type.GetField(n,Any)!=null?(T)type.GetField(n,Any).GetValue(rules):(T)type.GetProperty(n).GetValue(rules);void Tick(float s){for(int i=0;i<(int)Math.Ceiling(s/.05f);i++)Call("Tick",.05f);}int Serve(int slot=0,int cup=0,float fill=.85f,float spill=0,bool intact=true,bool settled=true,int guest=0,int intended=0)=>(int)Call("Serve",slot,cup,guest,intended,fill,spill,intact,settled);
  [SetUp]public void Reset(){type=Type.GetType("LWS.TruckTeaParty.TeaRules, Assembly-CSharp",true);rules=Activator.CreateInstance(type);Call("Reset",4,0);}
  [Test]public void CountdownAndAbsentPhysicalSettlementCannotAward(){Assert.That(Serve(),Is.Zero);Tick(3.1f);Assert.That(Serve(settled:false),Is.Zero);Assert.That(Get<int[]>("points"),Is.All.Zero);}
  [Test]public void WrongGuestBrokenEmptyOrWrongOwnerCannotBank(){Tick(3.1f);Assert.That(Serve(guest:1),Is.Zero);Assert.That(Serve(intact:false),Is.Zero);Assert.That(Serve(fill:.74f),Is.Zero);Assert.That(Serve(slot:4),Is.Zero);Assert.That(Serve(fill:float.NaN),Is.Zero);Assert.That(Get<int[]>("points"),Is.All.Zero);}
  [Test]public void CorrectPhysicalCupBanksOnlyOnceToActualCarrier(){Tick(3.1f);Assert.That(Serve(slot:2),Is.EqualTo(115));Assert.That(Serve(slot:1),Is.Zero);Assert.That(Get<int[]>("points")[2],Is.EqualTo(115));Assert.That(Get<int[]>("points")[1],Is.Zero);}
  [Test]public void PreciseFillScoresBetterThanBrimAndLowFill(){Tick(3.1f);int precise=Serve(cup:0),brim=Serve(cup:1,fill:1),low=Serve(cup:2,fill:.75f);Assert.That(precise,Is.GreaterThan(brim));Assert.That(precise,Is.GreaterThan(low));}
  [Test]public void ActualMissedTeaAndCupSpillsLowerServiceQuality(){Tick(3.1f);int clean=Serve(cup:0);Call("Spill",0,1f);int messy=Serve(cup:1,spill:.2f);Assert.That(messy,Is.LessThan(clean));Assert.That(Get<float[]>("spilled")[0],Is.EqualTo(1));}
  [Test]public void CourtesyNeedsActualPriorServiceOwnerVisitAndCompletedBow(){Tick(3.1f);Assert.That((int)Call("Courtesy",0,0,true,true),Is.Zero);Serve();Assert.That((int)Call("Courtesy",1,0,true,true),Is.Zero);Assert.That((int)Call("Courtesy",0,0,false,true),Is.Zero);Assert.That((int)Call("Courtesy",0,0,true,false),Is.Zero);Assert.That((int)Call("Courtesy",0,0,true,true),Is.EqualTo(15));Assert.That((int)Call("Courtesy",0,0,true,true),Is.Zero);}
  [Test]public void NativeLostCupCannotBecomeAReplacementScore(){Tick(3.1f);Call("Broken",0,0);Assert.That((bool)Call("CupDone",0),Is.True);Assert.That(Serve(),Is.Zero);Assert.That(Get<int[]>("broken")[0],Is.EqualTo(1));Assert.That(Get<int[]>("points"),Is.All.Zero);}
  [Test]public void FinalCupAllowsPhysicalCourtesyWindowBeforeResult(){Call("Reset",1,0);Tick(3.1f);for(int i=0;i<3;i++)Serve(cup:i);Tick(.2f);Assert.That(Get<bool>("Complete"),Is.False);Assert.That((int)Call("Courtesy",0,2,true,true),Is.EqualTo(15));Tick(5.2f);Assert.That(Get<bool>("Complete"),Is.True);}
  [Test]public void OriginalFiniteRosterRejectsUnusedGuestCups(){Call("Reset",1,0);Tick(3.1f);Assert.That(Serve(cup:3),Is.Zero);Assert.That(Serve(cup:0),Is.GreaterThan(0));}
  [Test]public void TimeoutAndRematchResetLivesAndScores(){Tick(184);Assert.That(Get<bool>("Complete"),Is.True);Call("Reset",4,1);Assert.That(Get<int[]>("points"),Is.All.Zero);Assert.That(Get<int[]>("served"),Is.All.Zero);Assert.That(Get<bool>("Complete"),Is.False);Assert.That(Get<float>("Remaining"),Is.EqualTo(240));}
  [Test]public void InvalidTimeOrSpillCannotCorruptState(){Call("Tick",float.NaN);Call("Tick",float.PositiveInfinity);Call("Tick",-1f);Assert.That(Get<float>("Clock"),Is.Zero);Tick(3.1f);Call("Spill",0,float.NaN);Call("Spill",0,-1f);Assert.That(Get<float[]>("spilled"),Is.All.Zero);}
  [Test]public void TiesShareActualScorePlace(){Tick(3.1f);Serve(slot:0,cup:0);Serve(slot:1,cup:3,guest:1,intended:1);Assert.That((int)Call("Place",0),Is.EqualTo(1));Assert.That((int)Call("Place",1),Is.EqualTo(1));Assert.That((int)Call("Place",2),Is.EqualTo(3));}
 }
}
